/** INVERSION-REG: un contrato del inventario clasificado por P181 (campos COMP = decimal empacado). */
public record InversionPte(
        int nodo,                     // 9(02)  llave de corte 1
        int sucursal,                 // 9(04)  llave de corte 2
        int producto,                 // 9(04)
        int instrumento,              // 9(04)
        int moneda,                   // 9(02)  1 = MN, 5 = DLL en las reglas del S151
        String contrato,              // 9(12)  String: conserva ceros a la izquierda
        String numCliente,            // 9(12)
        BigDecimal saldoAnterior,     // S9(13)V99: único par de importes con signo
        BigDecimal saldoActual,       // S9(13)V99
        BigDecimal saldoBloqueado,    // 9(12)V99
        BigDecimal saldoPendiente,    // 9(12)V99
        BigDecimal saldoPromedioMes,  // 9(12)V99
        BigDecimal autPendiente,      // 9(12)V99
        boolean medioTarjeta) {       // INV-BANTAR-S = 1: el contrato va al archivo de Tandem

    public boolean esAhorros()  { return producto == 500 && instrumento == 6; }
    public boolean esCtaMaestraTandem() {
        return producto == 66 || (producto == 500 && instrumento == 1);
    }
}

/** Registros de 90 bytes que P180 escribe. Cada uno lleva su clave de tipo en el primer campo. */
public sealed interface SalidaP180 permits S151Detalle, S151Trailer, TandemDetalle {}

/** WS-S151-DETALLE, clave 10. Campos COMP: el writer los empaca, no los formatea como texto. */
public record S151Detalle(int sistema, int sucursal, int moneda,
                          String cuenta,               // 9(19) COMP
                          int digito, int instrumento,
                          String nombre,               // X(30)
                          BigDecimal saldoAnterior,    // 9(18)V99 COMP, sin signo
                          BigDecimal saldoActual,
                          LocalDate fecha) implements SalidaP180 {
    public static final int CLAVE = 10;
}

/** WS-S151-TRAILER, clave 90: total de registros escritos, incluido el propio trailer. */
public record S151Trailer(int registros) implements SalidaP180 {
    public static final int CLAVE = 90, SISTEMA = 500;
}

/** WS-REGTB-DETALLE, tipo "1", para SALDOSTB (Cuenta Maestra) o SALDOSTBT (Cheques). */
public record TandemDetalle(String contrato, int producto, int instrumento, int moneda,
                            char signo,                       // siempre '+' en P180
                            BigDecimal saldoMn,               // 9(12)V99
                            int limiteCreditoMiles,           // 9(3)
                            int csi, int sucursal,
                            BigDecimal autPendMn,             // 9(08)V99
                            int status,
                            BigDecimal saldoDl, BigDecimal autPendDl) implements SalidaP180 {}

// FlatFileItemWriter<TandemDetalle> con FormatterLineAggregator:
//   "1%012d%04d%04d%03d%c%014d%03d%02d%04d%010d%d%014d%010d" + FILLER(7)
// Los importes se escriben sin punto decimal: unscaledValue() del BigDecimal con escala 2.

@Configuration
@EnableConfigurationProperties(P180Properties.class)
public class ReporteadorCaptacionJobConfig {

    /** 00000000-PRINCIPAL: cuatro PERFORM en secuencia y STOP RUN. */
    @Bean
    Job reporteadorCaptacion(JobRepository repo,
                             Step validaAmbiente,         // 10000010-NAME-HOST
                             Step fechaYAperturas,        // 10000000-LIBRERIAS + 20000000-OPEN
                             Step bloqueosPendientes,     // 50000100 .. 50000400 (tres copias BPEND)
                             Step enviaSaldosS151Cbii,    // 52200000 primer barrido de B03
                             Step enviaSaldosS151Resto,   // 52200000 segundo barrido de B03
                             Step generaSalidasInventario,// 53000000: un solo recorrido de INVE-PTE
                             Step reporteTefSemanal,      // 60000000, solo si es semanal
                             JobExecutionDecider esSemanal) {
        return new JobBuilder("S500P180", repo)
                .start(validaAmbiente).next(fechaYAperturas).next(bloqueosPendientes)
                .next(enviaSaldosS151Cbii).next(enviaSaldosS151Resto)
                .next(generaSalidasInventario)
                .next(esSemanal).on("SEMANAL").to(reporteTefSemanal)
                .from(esSemanal).on("*").end()
                .end()
                .build();
    }
}

